import openpyxl
wb = openpyxl.load_workbook('nasa_budget_incomplete.xlsx', data_only=False)
for name in wb.sheetnames:
    ws = wb[name]
    print('\nSheet', name)
    print('dimensions', ws.dimensions)
    for row in ws.iter_rows(min_row=1, max_row=30, min_col=1, max_col=15, values_only=True):
        if any(v is not None for v in row):
            # trim trailing None
            row_list = list(row)
            while row_list and row_list[-1] is None:
                row_list.pop()
            print(row_list)
